import http from 'k6/http';
import { check, sleep } from 'k6';
import { SharedArray } from 'k6/data';

// Load pre-authenticated users generated by scripts/seed-tier1.ts
const users = new SharedArray('users', function () {
  return JSON.parse(open('./users.json'));
});

// Target server URL (defaults to localhost:5000)
const BASE_URL = __ENV.BASE_URL || 'http://localhost:5000';

export const options = {
  // Gentle Tier 1 Load Curve (50 seconds total)
  stages: [
    { duration: '10s', target: 5 },  // Ramp-up to 5 concurrent users
    { duration: '30s', target: 10 }, // Hold steady at 10 concurrent users
    { duration: '10s', target: 0 },  // Graceful ramp-down to 0
  ],
  thresholds: {
    // Assertions: fail the test if errors exceed 1% or p95 is too slow
    http_req_failed: ['rate<0.01'],    // Error rate must be < 1%
    http_req_duration: ['p(95)<1000'], // 95% of requests should complete under 1s (includes cloud DB latency)
  },
};

export default function () {
  // 1. Initial Jitter on first iteration to stagger VU start
  if (__ITER === 0) {
    sleep(Math.random() * 3);
  }

  // 2. Select a unique user for this VU
  const user = users[(__VU - 1) % users.length];
  const headers = {
    'Content-Type': 'application/json',
    Authorization: `Bearer ${user.token}`,
  };

  // 3. Step 1: Fetch Notes Dashboard (100% of iterations)
  const listRes = http.get(`${BASE_URL}/api/notes/all`, {
    headers,
    tags: { name: 'GET /api/notes/all' },
  });

  const listOk = check(listRes, {
    'GET /api/notes/all status 200': (r) => r.status === 200,
  });

  if (!listOk) {
    sleep(2);
    return;
  }

  const notes = listRes.json('data') || [];

  // 4. Think Time (simulates human reviewing tasks)
  sleep(Math.random() * 2 + 1); // 1 to 3 seconds

  // 5. Probabilistic Branching
  const roll = Math.random() * 100;

  if (roll < 25) {
    // 25% Chance: Create a new Note
    const payload = JSON.stringify({
      title: `Task by ${user.username} @ ${Date.now()}`,
      body: 'Generated automatically during k6 load testing iteration',
      tag: 'work',
    });

    const createRes = http.post(`${BASE_URL}/api/notes`, payload, {
      headers,
      tags: { name: 'POST /api/notes' },
    });

    check(createRes, {
      'POST /api/notes status 201': (r) => r.status === 201,
    });
  } else if (roll < 43 && notes.length > 0) {
    // 18% Chance: Update an existing Note
    const randomNote = notes[Math.floor(Math.random() * notes.length)];
    const payload = JSON.stringify({
      title: `${randomNote.title} (Updated)`,
      body: randomNote.body,
      tag: randomNote.tag,
    });

    const updateRes = http.patch(
      `${BASE_URL}/api/notes/${randomNote.id}`,
      payload,
      {
        headers,
        tags: { name: 'PATCH /api/notes/:id' },
      }
    );

    check(updateRes, {
      'PATCH /api/notes/:id status 200': (r) => r.status === 200,
    });
  } else if (roll < 50 && notes.length > 0) {
    // 7% Chance: Delete a Note
    const randomNote = notes[Math.floor(Math.random() * notes.length)];

    const deleteRes = http.del(
      `${BASE_URL}/api/notes/${randomNote.id}`,
      null,
      {
        headers,
        tags: { name: 'DELETE /api/notes/:id' },
      }
    );

    check(deleteRes, {
      'DELETE /api/notes/:id status 200': (r) => r.status === 200,
    });
  }
  // Remaining 50%: Read-only session (no write operations)

  // 6. Idle cooldown before next loop
  sleep(Math.random() * 2 + 1); // 1 to 3 seconds
}
